function shopeeBatchIssues(){
  const issues=[],file=$('#shopeeBatchTemplate').files[0];
  if(!validShopeeBatchLimit())issues.push('กำหนดจำนวนสูงสุด 50–200 รายการ');
  else if(shopeeBatchItems.size>shopeeBatchLimit())issues.push(`เลือกสินค้าเกินจำนวนสูงสุด ${shopeeBatchLimit()} รายการ กรุณานำออก`);
  if(!shopeeBatchItems.size)issues.push('เพิ่มสินค้าเข้า Excel อย่างน้อย 1 รายการ');
  for(const item of shopeeBatchItems.values()){
    if(item.status!=='published')issues.push(`${item.meta_id}: เผยแพร่สินค้าใน VisionD ก่อน`);
  }
  if($('#shopeeBatchDelivery').value!=='เปิด')issues.push('เลือก Standard Delivery เป็น “เปิด” สำหรับทุกสินค้า');
  if(!file||!file.name.toLowerCase().endsWith('.xlsx')||file.size<1||file.size>2*1024*1024)issues.push('เลือกไฟล์ .xlsx ตัวอย่าง Shopee ไม่เกิน 2 MB');
  return issues;
}
function updateShopeeBatchState(){const issues=shopeeBatchIssues();$('#shopeeBatchDownload').disabled=Boolean(issues.length||shopeeBatchAbort);status('#shopeeBatchStatus',issues.length?`ยังส่งออกไม่ได้: ${issues.join(' · ')}`:shopeeBatchAbort?'กำลังตรวจสินค้าและสร้าง Excel รวม…':'พร้อมตรวจสินค้าทุกชิ้นและสร้าง Excel ไฟล์เดียว',Boolean(issues.length))}
function touchShopeeBatch(){shopeeBatchAbort?.abort();shopeeBatchAbort=null;shopeeBatchRevision++;updateShopeeBatchState()}
function renderShopeeBatch(){const root=$('#shopeeBatchList');root.replaceChildren();$('#shopeeBatchCount').textContent=`เลือกแล้ว ${shopeeBatchItems.size}/${validShopeeBatchLimit()?shopeeBatchLimit():'—'} รายการ`;$('#shopeeBatchClear').disabled=!shopeeBatchItems.size;let order=0;for(const item of shopeeBatchItems.values()){
  const row=document.createElement('div'),info=document.createElement('div'),title=document.createElement('strong'),detail=document.createElement('small'),remove=document.createElement('button');row.className='shopee-batch-row';title.textContent=`${++order}. ${item.title}`;detail.textContent=`${item.meta_id} · ${item.status==='published'?'เผยแพร่':'ฉบับร่าง'}`;info.append(title,detail);remove.type='button';remove.className='vds-btn vds-btn--text';remove.textContent='เอาออก';remove.setAttribute('aria-label',`เอา ${item.meta_id} ออกจาก Excel`);remove.onclick=()=>{shopeeBatchItems.delete(item.id);touchShopeeBatch();renderShopeeBatch();renderShopeeResults()};row.append(info,remove);root.append(row)}updateShopeeBatchState()}
function addShopeeBatchItem(item){const id=Number(item.id);if(!Number.isSafeInteger(id)||id<1||shopeeBatchItems.has(id))return;if(!validShopeeBatchLimit()||shopeeBatchItems.size>=shopeeBatchLimit()){status('#shopeeBatchStatus',`กำหนดจำนวนสูงสุด 50–200 รายการ และเลือกไม่เกิน ${validShopeeBatchLimit()?shopeeBatchLimit():200} รายการต่อไฟล์`,true);return}shopeeBatchItems.set(id,{id,title:String(item.title||''),meta_id:String(item.meta_id||''),status:item.status});touchShopeeBatch();renderShopeeBatch();renderShopeeResults()}
function clearShopeeBatch(){shopeeBatchItems.clear();$('#shopeeBatchTemplate').value='';$('#shopeeBatchDelivery').value='';touchShopeeBatch();renderShopeeBatch();renderShopeeResults()}
function removeDeletedShopeeBatchItem(productId){const id=Number(productId);shopeeItems=shopeeItems.filter(item=>Number(item.id)!==id);if(shopeeBatchItems.delete(id)){touchShopeeBatch();renderShopeeBatch();status('#shopeeBatchStatus',`นำสินค้า #${id} ที่ลบแล้วออกจากคิว Excel`)}renderShopeeResults()}
async function downloadShopeeBatch(){
  if(shopeeBatchIssues().length){updateShopeeBatchState();return}
  const revision=shopeeBatchRevision,items=[...shopeeBatchItems.values()].map(item=>({id:item.id})),controller=new AbortController(),chunks=[];
  shopeeBatchAbort=controller;updateShopeeBatchState();
  try{
    for(let start=0;start<items.length;start+=10){
      const form=new FormData();form.set('mode','prepare');form.set('items',JSON.stringify(items.slice(start,start+10)));form.set('standard_delivery',$('#shopeeBatchDelivery').value);
      const response=await fetch(stockUrl('/api/admin/toys-center/shopee-xlsx'),{method:'POST',body:form,cache:'no-store',signal:controller.signal});
      if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error((data.errors||[data.error||'ตรวจสินค้า Shopee ไม่สำเร็จ']).join(' · '))}
      const data=await response.json();if(controller.signal.aborted||revision!==shopeeBatchRevision)return;
      if(!data.chunk)throw new Error('ชุดข้อมูลสินค้า Shopee ไม่ครบ');chunks.push(data.chunk);
      status('#shopeeBatchStatus',`ตรวจสินค้าแล้ว ${Math.min(start+10,items.length)}/${items.length} รายการ`);
    }
    const form=new FormData();form.set('mode','compile');form.set('items',JSON.stringify(items));form.set('chunks',JSON.stringify(chunks));form.set('template',$('#shopeeBatchTemplate').files[0]);
    const response=await fetch(stockUrl('/api/admin/toys-center/shopee-xlsx'),{method:'POST',body:form,cache:'no-store',signal:controller.signal});
    if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error((data.errors||[data.error||'สร้าง Excel รวมไม่สำเร็จ']).join(' · '))}
    if(!String(response.headers.get('content-type')||'').startsWith('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'))throw new Error('เซิร์ฟเวอร์ไม่ได้ส่งไฟล์ Excel');
    const blob=await response.blob();if(controller.signal.aborted||revision!==shopeeBatchRevision)return;
    const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`visiond-shopee-${items.length}-products.xlsx`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0);status('#shopeeBatchStatus',`ดาวน์โหลด Excel รวม ${items.length} สินค้าแล้ว โปรดตรวจผลนำเข้าที่ Shopee Seller Centre`);
  }catch(error){if(!controller.signal.aborted&&revision===shopeeBatchRevision)status('#shopeeBatchStatus',error.message,true)}finally{if(shopeeBatchAbort===controller){shopeeBatchAbort=null;$('#shopeeBatchDownload').disabled=Boolean(shopeeBatchIssues().length)}}
}
$('#shopeeBatchClear').onclick=clearShopeeBatch;
$('#shopeeBatchLimit').addEventListener('input',()=>{touchShopeeBatch();renderShopeeBatch();renderShopeeResults()});
$('#shopeeBatchDelivery').onchange=touchShopeeBatch;
$('#shopeeBatchTemplate').onchange=touchShopeeBatch;
$('#shopeeBatchDownload').onclick=downloadShopeeBatch;
renderShopeeBatch();

const THAIMART_CACHE_TTL=30000,thaiMartSearchCache=new Map(),thaiMartSearchInflight=new Map(),thaiMartPreviewCache=new Map(),thaiMartPreviewInflight=new Map();
let thaiMartQuery='',thaiMartCursor='',thaiMartItems=[],thaiMartGeneration=0,thaiMartIntent=0,thaiMartPreviewIntent=0,selectedThaiMartProduct=null,selectedThaiMartSnapshot=null,thaiMartDebounceTimer=0;
const normalizeThaiMartQuery=value=>String(value||'').normalize('NFKC').trim().toLocaleLowerCase('th-TH').replace(/\s+/g,' ');
function thaiMartCacheGet(cache,key){const entry=cache.get(key);if(!entry||Date.now()-entry.at>THAIMART_CACHE_TTL){cache.delete(key);return null}return entry.value}
async function thaiMartCachedApi(path,cache,inflight,key){const cached=thaiMartCacheGet(cache,key);if(cached)return cached;if(inflight.has(key))return inflight.get(key);const request=api(path,{cache:'no-store'}).then(value=>{cache.set(key,{at:Date.now(),value});return value}).finally(()=>inflight.delete(key));inflight.set(key,request);return request}
function invalidateThaiMartWorkspace(productId){thaiMartGeneration++;thaiMartSearchCache.clear();thaiMartPreviewCache.clear();if(Number(productId)===Number(selectedThaiMartProduct?.id))clearThaiMartSelection();if(thaiMartQuery)scheduleThaiMartSearch(0)}
function invalidateExportWorkspaces(productId){invalidateShopeeWorkspace(productId);invalidateThaiMartWorkspace(productId)}
function clearThaiMartSelection(){selectedThaiMartProduct=null;selectedThaiMartSnapshot=null;thaiMartPreviewIntent++;$('#thaiMartPreview').hidden=true;$('#clearThaiMartProduct').hidden=true;for(const button of document.querySelectorAll('.thaimart-result'))button.setAttribute('aria-selected','false')}
function renderThaiMartResults(){const root=$('#thaiMartSearchResults');root.replaceChildren();for(const item of thaiMartItems){const button=document.createElement('button'),copy=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small'),action=document.createElement('b');button.type='button';button.className='shopee-result thaimart-result';button.dataset.productId=String(item.id);button.setAttribute('role','option');button.setAttribute('aria-selected',String(Number(selectedThaiMartProduct?.id)===Number(item.id)));title.textContent=item.title;detail.textContent=`${item.meta_id} · ${item.status==='published'?'เผยแพร่':'ฉบับร่าง'}`;action.textContent='เลือก';copy.append(title,detail);button.append(copy,action);button.onclick=()=>selectThaiMartProduct(item);root.append(button)}$('#moreThaiMartProducts').hidden=!thaiMartCursor}
async function loadThaiMartProducts(reset=true){const query=normalizeThaiMartQuery($('#thaiMartSearchInput').value),intent=++thaiMartIntent,generation=thaiMartGeneration;if(!query){thaiMartQuery='';thaiMartCursor='';thaiMartItems=[];renderThaiMartResults();status('#thaiMartSearchStatus','พิมพ์ชื่อเพื่อค้นหา');return}if(reset){thaiMartQuery=query;thaiMartCursor='';thaiMartItems=[];renderThaiMartResults()}const cursor=reset?'':thaiMartCursor,key=`${generation}|${query}|${cursor}`,params=new URLSearchParams({q:query,limit:'24'});if(cursor)params.set('cursor',cursor);status('#thaiMartSearchStatus',reset?'กำลังค้นหาชื่อสินค้า…':'กำลังโหลดชื่อถัดไป…');try{const data=await thaiMartCachedApi(`/api/admin/toys-center/thaimart-products?${params}`,thaiMartSearchCache,thaiMartSearchInflight,key);if(intent!==thaiMartIntent||generation!==thaiMartGeneration||query!==thaiMartQuery)return;const known=new Set(thaiMartItems.map(item=>Number(item.id)));thaiMartItems.push(...data.items.filter(item=>!known.has(Number(item.id))));thaiMartCursor=data.pagination.next_cursor||'';renderThaiMartResults();status('#thaiMartSearchStatus',thaiMartItems.length?`พบ ${thaiMartItems.length.toLocaleString('th-TH')} รายการ${thaiMartCursor?' · มีชื่อถัดไป':''}`:'ไม่พบสินค้าที่ขึ้นต้นด้วยชื่อนี้')}catch(error){if(intent===thaiMartIntent)status('#thaiMartSearchStatus',error.message,true)}}
function scheduleThaiMartSearch(delay=300){clearTimeout(thaiMartDebounceTimer);thaiMartDebounceTimer=setTimeout(()=>loadThaiMartProducts(true),delay)}
async function selectThaiMartProduct(item){const intent=++thaiMartPreviewIntent,generation=thaiMartGeneration,key=`${generation}|${item.id}|${item.updated_at}`;selectedThaiMartProduct=item;selectedThaiMartSnapshot=null;renderThaiMartResults();$('#clearThaiMartProduct').hidden=false;$('#thaiMartPreview').hidden=false;$('#thaiMartPreviewTitle').textContent=`กำลังโหลด ${item.title}…`;$('#thaiMartValidationStatus').textContent='';$('#thaiMartJsonText').textContent='';$('#downloadThaiMartJson').disabled=true;try{const data=await thaiMartCachedApi(`/api/admin/toys-center/${item.id}/thaimart-export`,thaiMartPreviewCache,thaiMartPreviewInflight,key);if(intent!==thaiMartPreviewIntent||generation!==thaiMartGeneration||Number(selectedThaiMartProduct?.id)!==Number(item.id))return;selectedThaiMartSnapshot=data;$('#thaiMartPreviewTitle').textContent=`JSON v${data.version} · ${data.product.name}`;const validation=$('#thaiMartValidationStatus');validation.className=data.validation.complete?'shopee-validation--complete':'shopee-validation--incomplete';validation.textContent=data.validation.complete?'ข้อมูลครบ พร้อมส่งต่อ':'ข้อมูลยังไม่ครบ: '+data.validation.missing.join(', ');$('#thaiMartJsonText').textContent=JSON.stringify(data,null,2);$('#downloadThaiMartJson').disabled=false}catch(error){if(intent===thaiMartPreviewIntent){status('#thaiMartValidationStatus',error.message,true);$('#thaiMartPreviewTitle').textContent='โหลดตัวอย่าง JSON ไม่สำเร็จ'}}}
function downloadThaiMartJson(){if(!selectedThaiMartSnapshot)return;const bytes=`${JSON.stringify(selectedThaiMartSnapshot,null,2)}\n`,blob=new Blob([bytes],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`visiond-thaimart-v1-${selectedThaiMartSnapshot.product.visiond_product_id}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0)}
$('#thaiMartSearchInput').addEventListener('input',()=>{clearThaiMartSelection();scheduleThaiMartSearch()});
$('#moreThaiMartProducts').onclick=()=>loadThaiMartProducts(false);
$('#clearThaiMartProduct').onclick=clearThaiMartSelection;
$('#downloadThaiMartJson').onclick=downloadThaiMartJson;
